@Component("documentSecurity")
public class DocumentSecurityService {

    @Autowired private DocumentRepository documentRepository;

    public boolean canRead(Authentication auth, Long docId) {
        return documentRepository.findById(docId)
            .map(doc ->
                doc.getOwnerUsername().equals(auth.getName()) ||
                doc.getSharedWithUsernames().contains(auth.getName())
            )
            .orElse(false);
    }

    public boolean canDelete(Authentication auth, Long docId) {
        return auth.getAuthorities().stream()
            .anyMatch(a -> a.getAuthority().equals("ROLE_ADMIN"));
    }
}

